mapper.select:
select u.id,u.username,u.status,u.deleted,u.create_time,u.update_time, mp.shop_name,mp.shop_logo,mp.contact_phone from user u left join merchant_profile mp on u.id = mp.user_id
and u.role = 2
and username like concat('%',#{dto.keyword},'%')
and status = #{dto.status}
and deleted = #{dto.deleted}
order by u.create_time desc

select shop_name from merchant_profile

    shop_name = #{shopName}

        and user_id != #{merchantId}

select contact_phone from merchant_profile

        contact_phone = #{contactPhone}

    and user_id != #{userId}
